function buildBatchUserPrompt(jobs) {
  const serialized = jobs.map(
    (job) => `--- \u6C42\u4EBA index=${job.index} ---
\u8077\u7A2E\u540D: ${job.title || "(\u7A7A\u6B04)"}
\u4ED5\u4E8B\u5185\u5BB9: ${(job.description || "(\u8A18\u8F09\u306A\u3057)").slice(0, 2500)}`
  ).join("\n\n");
  return `\u4EE5\u4E0B\u306E ${jobs.length} \u4EF6\u306E\u6C42\u4EBA\u30C7\u30FC\u30BF\u3092\u305D\u308C\u305E\u308C\u72EC\u7ACB\u3057\u3066\u5206\u6790\u3057\u3001\u5404 index \u306B\u5BFE\u5FDC\u3059\u308B\u5206\u985E\u7D50\u679C\u3092 JSON \u914D\u5217 results \u306B\u683C\u7D0D\u3057\u3066\u8FD4\u3057\u3066\u304F\u3060\u3055\u3044\u3002

${serialized}`;
}

