async function classifySingleJob(params) {
  const start = Date.now();
  const hashMode = params.hashMode || "title_and_content";
  const master = masterStore.getMasterData();
  const title = (params.title || "").trim();
  const description = (params.description || "").trim();
  const hash = computeJobMd5Hash(title, description, hashMode);
  const cacheKey = buildCacheKey(params.platform, hashMode, hash);
  const cached = cacheStore.get(cacheKey);
  if (cached) {
    return hydrateResult(
      params.platform,
      title,
      description,
      hash,
      hashMode,
      cached.categories,
      cached.reasoning,
      cached.confidence,
      true,
      0,
      master,
      "MD5 Cache"
    );
  }
  if (!title && !description) {
    return hydrateResult(
      params.platform,
      title,
      description,
      hash,
      hashMode,
      ["NONE"],
      "\u8077\u7A2E\u540D\u3068\u4ED5\u4E8B\u5185\u5BB9\u304C\u7A7A\u6B04\u306E\u305F\u3081\u5224\u5B9A\u3067\u304D\u307E\u305B\u3093\u3002",
      0,
      false,
      Date.now() - start,
      master
    );
  }
  const systemInstruction = buildSystemInstruction(params.platform, master);
  const userPrompt = buildBatchUserPrompt([{ index: 0, title, description }]);
  const { items, modelUsed, fallbackNotice } = await callGeminiWithFallback(
    systemInstruction,
    userPrompt
  );
  const matched = items.find((i) => i.index === 0) ?? items[0];
  const result = hydrateResult(
    params.platform,
    title,
    description,
    hash,
    hashMode,
    matched?.categories ?? ["NONE"],
    matched?.reasoning ?? "\u5206\u985E\u7D50\u679C\u3092\u53D6\u5F97\u3067\u304D\u307E\u305B\u3093\u3067\u3057\u305F\u3002",
    matched?.confidence ?? 0,
    false,
    Date.now() - start,
    master,
    modelUsed,
    fallbackNotice
  );
  cacheStore.set(cacheKey, result);
  return result;
}
async function classifyBatchJobs(params) {
  const hashMode = params.hashMode || "title_and_content";
  const batchSize = Math.max(1, Math.min(15, params.batchSize || 10));
  const master = masterStore.getMasterData();
  const total = params.jobs.length;
  const outputResults = new Array(total);
  let processed = 0;
  let cacheHits = 0;
  let aiCalls = 0;
  let noneCount = 0;
  let errorCount = 0;
  const noticeSet = /* @__PURE__ */ new Set();
  const uncachedByHash = /* @__PURE__ */ new Map();
  const cachedChunkResults = [];
  for (let i = 0; i < total; i++) {
    const job = params.jobs[i];
    const title = (job.title || "").trim();
    const description = (job.description || "").trim();
    const hash = computeJobMd5Hash(title, description, hashMode);
    const cacheKey = buildCacheKey(params.platform, hashMode, hash);
    if (!title && !description) {
      const emptyRes = {
        ...hydrateResult(
          params.platform,
          title,
          description,
          hash,
          hashMode,
          ["NONE"],
          "\u8077\u7A2E\u540D\u30FB\u4ED5\u4E8B\u5185\u5BB9\u304C\u672A\u5165\u529B\u306E\u305F\u3081 NONE \u3068\u5224\u5B9A\u3057\u307E\u3057\u305F\u3002",
          100,
          false,
          0,
          master
        ),
        id: job.id,
        rowIndex: job.rowIndex ?? i
      };
      outputResults[i] = emptyRes;
      cachedChunkResults.push(emptyRes);
      processed += 1;
      noneCount += 1;
      continue;
    }
    const cached = cacheStore.get(cacheKey);
    if (cached) {
      const hitRes = {
        ...hydrateResult(
          params.platform,
          title,
          description,
          hash,
          hashMode,
          cached.categories,
          cached.reasoning,
          cached.confidence,
          true,
          0,
          master,
          "MD5 Cache"
        ),
        id: job.id,
        rowIndex: job.rowIndex ?? i
      };
      outputResults[i] = hitRes;
      cachedChunkResults.push(hitRes);
      processed += 1;
      cacheHits += 1;
      if (hitRes.isNone) noneCount += 1;
      continue;
    }
    const group = uncachedByHash.get(cacheKey) || [];
    group.push({
      originalIdx: i,
      job,
      title,
      description,
      hash,
      cacheKey
    });
    uncachedByHash.set(cacheKey, group);
  }
  if (cachedChunkResults.length > 0 && params.onProgress) {
    params.onProgress({
      type: "progress",
      total,
      processed,
      cacheHits,
      aiCalls,
      noneCount,
      errorCount,
      chunkResults: cachedChunkResults
    });
  }
  const uniqueGroups = Array.from(uncachedByHash.values());
  if (uniqueGroups.length > 0) {
    const systemInstruction = buildSystemInstruction(params.platform, master);
    const chunks = chunkArray(uniqueGroups, batchSize);
    for (const chunk of chunks) {
      const chunkStart = Date.now();
      const promptItems = chunk.map((group, idx) => ({
        index: idx,
        title: group[0].title,
        description: group[0].description
      }));
      try {
        aiCalls += 1;
        const { items: aiItems, modelUsed, fallbackNotice } = await callGeminiWithFallback(
          systemInstruction,
          buildBatchUserPrompt(promptItems)
        );
        if (fallbackNotice) {
          noticeSet.add(fallbackNotice);
        }
        const chunkLatency = Date.now() - chunkStart;
        const toCache = [];
        const emittedChunkResults = [];
        chunk.forEach((group, idx) => {
          const matched = aiItems.find((r) => r.index === idx);
          const representative = group[0];
          const baseResult = hydrateResult(
            params.platform,
            representative.title,
            representative.description,
            representative.hash,
            hashMode,
            matched?.categories ?? ["NONE"],
            matched?.reasoning ?? "AI\u5FDC\u7B54\u306B\u8A72\u5F53\u30A4\u30F3\u30C7\u30C3\u30AF\u30B9\u304C\u542B\u307E\u308C\u307E\u305B\u3093\u3067\u3057\u305F\u3002",
            matched?.confidence ?? 0,
            false,
            chunkLatency,
            master,
            modelUsed,
            fallbackNotice
          );
          toCache.push({ key: representative.cacheKey, result: baseResult });
          group.forEach((member, dupIdx) => {
            const isInBatchDup = dupIdx > 0;
            if (isInBatchDup) cacheHits += 1;
            if (baseResult.isNone) noneCount += 1;
            const rowRes = {
              ...baseResult,
              title: member.title,
              description: member.description,
              fromCache: isInBatchDup,
              latencyMs: isInBatchDup ? 0 : chunkLatency,
              id: member.job.id,
              rowIndex: member.job.rowIndex ?? member.originalIdx
            };
            outputResults[member.originalIdx] = rowRes;
            emittedChunkResults.push(rowRes);
            processed += 1;
          });
        });
        cacheStore.setMany(toCache);
        if (params.onProgress) {
          params.onProgress({
            type: "progress",
            total,
            processed,
            cacheHits,
            aiCalls,
            noneCount,
            errorCount,
            notice: fallbackNotice,
            chunkResults: emittedChunkResults
          });
        }
      } catch (err) {
        const msg = err instanceof Error ? err.message : formatGeminiError(err).message;
        const failedChunkResults = [];
        for (const group of chunk) {
          for (const member of group) {
            errorCount += 1;
            processed += 1;
            const failRes = {
              ...hydrateResult(
                params.platform,
                member.title,
                member.description,
                member.hash,
                hashMode,
                ["NONE"],
                msg,
                0,
                false,
                0,
                master
              ),
              id: member.job.id,
              rowIndex: member.job.rowIndex ?? member.originalIdx,
              error: msg
            };
            outputResults[member.originalIdx] = failRes;
            failedChunkResults.push(failRes);
          }
        }
        if (params.onProgress) {
          params.onProgress({
            type: "progress",
            total,
            processed,
            cacheHits,
            aiCalls,
            noneCount,
            errorCount,
            notice: msg,
            chunkResults: failedChunkResults
          });
        }
      }
    }
  }
  return {
    results: outputResults,
    cacheHits,
    aiCalls,
    noneCount,
    errorCount,
    notices: Array.from(noticeSet)
  };
}

